# -*- coding: utf-8 -*-
"""The 7 App Store screenshot screens — using REAL app screenshots from /upload
wrapped in a premium device frame, with localized glassmorphic ASO callouts."""

from templates_base import icon, GREEN, ROSE, WHITE
import base64, os

ASSET_DIR = os.path.join(os.path.dirname(__file__), "assets", "app-ui")
_appshot_cache = {}

def appshot(name):
    if name not in _appshot_cache:
        p = os.path.join(ASSET_DIR, f"{name}.jpeg")
        with open(p, "rb") as f:
            b64 = base64.b64encode(f.read()).decode()
        _appshot_cache[name] = f"data:image/jpeg;base64,{b64}"
    return _appshot_cache[name]

def _frame(img_name):
    return f'<div class="island"></div><img class="appshot" src="{appshot(img_name)}" alt="">'

def _callout(icon_name, title, sub, color, bottom=150):
    cls = "rose" if color == ROSE else "green"
    return f'<div class="callout {cls}" style="bottom:{bottom}px"><div class="ci">{icon(icon_name,44,color,2)}</div><div><div class="ct">{title}</div><div class="cs">{sub}</div></div></div>'

def _pill(icon_name, title, sub, color=GREEN):
    return f'<div class="pill"><div class="pi">{icon(icon_name,34,color,2)}</div><div><div class="pt">{title}</div><div class="ps">{sub}</div></div></div>'

