def _c(lang):
    return CALL.get(lang, CALL["en-US"])

def shot1(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("nowplaying")+_callout("airplane",c["offline_t"],c["offline_s"],GREEN,150)
def shot2(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("equalizer")+_callout("sliders",c["eq_t"],c["eq_s"],ROSE,150)
def shot3(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("library")+_callout("folder",c["organize_t"],c["organize_s"],GREEN,150)
def shot4(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("search")+_callout("search",c["search_t"],c["search_s"],ROSE,150)
def shot5(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("home")+_callout("queue",c["playlist_t"],c["playlist_s"],GREEN,150)
def shot6(ui, covers, lang="en-US"):
    c=_c(lang); return _frame("nowplaying")+_callout("quote",c["immersive_t"],c["immersive_s"],ROSE,150)
def shot7(ui, covers, lang="en-US"):
    c=_c(lang)
    return _frame("settings1")+f'<div class="pills" style="bottom:150px">{_pill("airplane",c["p_off_t"],c["p_off_s"],GREEN)}{_pill("sliders",c["p_eq_t"],c["p_eq_s"],ROSE)}</div><div class="pills" style="bottom:300px">{_pill("quote",c["p_lyrics_t"],c["p_lyrics_s"],ROSE)}{_pill("wave",c["p_hires_t"],c["p_hires_s"],GREEN)}</div>'

